using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EndTurnConditionCorruptOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EndTurnConditionCorruptOmenData")]
public class EndTurnConditionCorruptOmenData : EndTurnConditionOmenData
{
	private Action<GameObject, GameObject, int> omenAction;

	public override void InitializeCondition()
	{
		omenAction = delegate(GameObject target, GameObject source, int amount)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && ReferenceSingleton<BattleHandler>.Instance.IsTargetPlayer(target))
			{
				ActivateOmen();
			}
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptOmenActions.Remove(omenAction);
		base.OmenRemoved();
	}
}
